cat >> packs/node/test/pack.test.mjs <<'EOF'

const printThenExit = declaredCheck('packs/node', 'node/print-then-exit');

test('node/print-then-exit: flags a print and a hard exit added on one line', () => {
  const root = makeRepo({
    base: { 'cli.mjs': 'const go = () => 1;\n' },
    changed: { 'cli.mjs': "const go = () => 1;\nif (!go()) { console.error('no'); process.exit(1); }\n" },
  });
  try {
    const findings = run(printThenExit, root);
    assert.equal(findings.length, 1);
    assert.equal(findings[0].file, 'cli.mjs');
    assert.equal(findings[0].severity, 'advisory'); // blocking, inside its `since` grace
    assert.match(findings[0].fix, /process\.exitCode/);
  } finally { cleanup(root); }
});

test('node/print-then-exit: exitCode with a return in its place is clean', () => {
  const root = makeRepo({
    base: { 'cli.mjs': 'const go = () => 1;\n' },
    changed: { 'cli.mjs': "const go = () => 1;\nif (!go()) { console.error('no'); process.exitCode = 1; return; }\n" },
  });
  try {
    assert.equal(run(printThenExit, root).length, 0);
  } finally { cleanup(root); }
});

// The sanctioned holdout the rule names: a hook whose exit code IS its protocol,
// exiting from the write's own callback so nothing is queued when it goes.
test('node/print-then-exit: exiting from the write callback is clean', () => {
  const root = makeRepo({
    base: { 'hook.mjs': 'const verdict = {};\n' },
    changed: { 'hook.mjs': 'const verdict = {};\nprocess.stderr.write(verdict.block, () => process.exit(2));\n' },
  });
  try {
    assert.equal(run(printThenExit, root).length, 0);
  } finally { cleanup(root); }
});

// A comment documenting the hazard is where a naive matcher trips over its own
// reasoning — engine/checks/check_the_world.mjs carries exactly such a comment.
test('node/print-then-exit: a comment describing the pattern is not an instance', () => {
  const root = makeRepo({
    base: { 'cli.mjs': 'const go = () => 1;\n' },
    changed: { 'cli.mjs': "const go = () => 1;\n// never console.error('no'); process.exit(1); — the write is still queued\n" },
  });
  try {
    assert.equal(run(printThenExit, root).length, 0);
  } finally { cleanup(root); }
});
EOF
