  const dir = mkdtempSync(join(tmpdir(), 'claudinite-wrapped-'));
  writeFileSync(join(dir, 'task.json'), JSON.stringify({ id: 'p/t' }));
  writeFileSync(join(dir, 'worker.mjs'), 'export const worker = () => { throw new Error("nope"); };\\n');
