      taskDir: dir,
      env: { ...process.env, CLAUDINITE_PACK: 'p', CLAUDINITE_TASK: 't' },
      timeoutSeconds: 60,
      echo: () => {},
    });
    assert.equal(result.ok, false);
    assert.equal(result.code, 1);
    assert.match(result.stderr, /p\\/t failed after .*: nope/);
  } finally { removeTree(dir); }
});
'''
open(p,'w').write(t)
print('ok')
PY

