1	// The verify-production code-work (#1530) — the I/O shell around probes.mjs. It
2	// runs Action-side, which is the whole reason this task exists: an agent session
3	// has no egress, so a verification whose artifact is a live URL (a Pages site, a
4	// deployed config) can only be read from here.
5	//
6	// Four verdicts, each its own exit:
7	//   invalid  — the spec is unreadable: the triage marker names every problem and
8	//              the exit is non-zero, so the item parks with the list.
9	//   not-live — a liveness probe failed: print the requeue marker with
10	//              now + Retry-every and exit clean; the executor re-arms the item.
11	//   pass     — comment the evidence on the item and exit clean; the executor
12	//              closes it done.
13	//   fail     — reopen Original-issue with the evidence (the verification did its
14	//              job by finding the fault, which is now that issue's), link it from
15	//              the item, and exit clean.
16	
17	import { pathToFileURL } from 'node:url';
18	import { humanTextOf } from '../../public/work-item-grammar.mjs';
19	import { parseVerificationSpec, runProbes, renderResult } from './probes.mjs';
20	import { getIssue, reopenIssue, comment as ghComment } from '../../src/world/github.mjs';
21	
22	const FETCH_TIMEOUT_MS = 30_000;
23	const BODY_CAP = 2 * 1024 * 1024;
24	
25	// One live fetch: bounded, redirect-following, body capped. A network error is
26	// retried once — a single blip must not reopen an issue — and the second failure
27	// is the answer.
28	export async function fetchOnce(url) {
29	  const attempt = async () => {
30	    const res = await fetch(url, { redirect: 'follow', signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });
31	    const body = (await res.text()).slice(0, BODY_CAP);
32	    return { status: res.status, body };
33	  };
34	  try { return await attempt(); } catch { return attempt(); }
35	}
36	
37	// The whole judgment, injectable for tests: reads the item, parses the spec out
38	// of the HUMAN half of its body (the machine block is the queue's), runs the
39	// probes, and lands the verdict's writes. Returns what main() turns into markers
40	// and an exit code.
41	export async function runVerification({ gh, repo, itemNumber, fetchUrl, now = () => new Date(), log = console.log }) {
42	  const { status, json: item } = await getIssue(gh, repo, itemNumber);
43	  if (status !== 200) throw new Error(`could not read item #${itemNumber}: ${status}`);
44	  const spec = parseVerificationSpec(humanTextOf(item.body));
45	  if (spec.problems.length) return { outcome: 'invalid', problems: spec.problems };
46	
47	  const live = await runProbes(spec.live, fetchUrl);
48	  for (const r of live) log(`liveness: ${renderResult(r)}`);
49	  if (!live.every((r) => r.ok)) {
50	    const firstFail = live.find((r) => !r.ok);
51	    return {
52	      outcome: 'not-live',
53	      until: new Date(now().getTime() + spec.retryEveryMs).toISOString(),
54	      reason: `not yet live: ${renderResult(firstFail)}`,
55	    };
56	  }
57	
58	  const verify = await runProbes(spec.verify, fetchUrl);
59	  for (const r of verify) log(`verify: ${renderResult(r)}`);
60	  const evidence = verify.map((r) => `- ${renderResult(r)}`).join('\n');
61	  if (verify.every((r) => r.ok)) {
62	    await ghComment(gh, repo, itemNumber, `Production verification PASSED. What was read:\n\n${evidence}`);
63	    return { outcome: 'pass' };
64	  }
65	
66	  // The verification did its job by finding the fault — which is now the
67	  // original issue's, reopened with what was asserted and what was read.
68	  await reopenIssue(gh, repo, spec.originalIssue);
69	  await ghComment(gh, repo, spec.originalIssue,
70	    `The production verification filed for this change (#${itemNumber}) FAILED against the live artifact:\n\n${evidence}\n\n`
71	    + 'The release is live (every liveness probe passed), so this is a fault in production, not a wait.');
72	  await ghComment(gh, repo, itemNumber,
73	    `Verification FAILED — reopened #${spec.originalIssue} with the evidence:\n\n${evidence}`);
74	  return { outcome: 'fail', originalIssue: spec.originalIssue };
75	}
76	
77	export async function main() {
78	  const repo = process.env.CLAUDINITE_REPO;
79	  const itemNumber = Number(process.env.CLAUDINITE_ITEM);
80	  if (!repo || !itemNumber) throw new Error('CLAUDINITE_REPO / CLAUDINITE_ITEM not set — not running under the executor');
81	  if (!process.env.GITHUB_TOKEN) throw new Error('GITHUB_TOKEN is not set — the verification cannot read its item');
82	  const { makeGh } = await import('../../src/world/github.mjs');
83	  const verdict = await runVerification({ gh: makeGh(), repo, itemNumber, fetchUrl: fetchOnce });
84	
85	  if (verdict.outcome === 'invalid') {
86	    console.log(`claudinite-needs-human: action — this verification's probe spec is unreadable: ${verdict.problems.join('; ')}`);
87	    process.exitCode = 1;
88	    return;
89	  }
90	  if (verdict.outcome === 'not-live') {
91	    console.log(`claudinite-requeue: ${verdict.until} — ${verdict.reason}`);
92	    return;
93	  }
94	  console.log(`verification ${verdict.outcome === 'pass' ? 'passed' : `failed — reopened #${verdict.originalIssue}`}`);
95	}
96	
97	// Run only when invoked directly (code-work's `node worker.mjs`), never on import.
98	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
99	  main().catch((e) => { console.error(`verify-production failed: ${e.message}`); process.exitCode = 1; });
100	}

