32	// carry - which secrets this task asked for - rather than passed in a channel of its
33	// own: the module sits in its task directory, so the declaration is already here.
34	function declaredSecretNames(taskDir) {
35	  try {
36	    const decl = JSON.parse(readFileSync(resolve(taskDir, 'task.json'), 'utf8'));
37	    const names = decl.code_work_required_secrets ?? decl.required_secrets;
38	    return Array.isArray(names) ? names.filter((n) => typeof n === 'string') : [];
39	  } catch {
40	    // A task whose declaration cannot be read here is one the executor validated
41	    // before spawning this process, so the file is present and parseable in every
42	    // real run; an empty bag is the honest answer for the cases that are not.
43	    return [];
44	  }
45	}
