47	// The bag a worker is called with. Absence is preserved rather than defaulted: a
48	// target this run has no pull request for reads `null`, never 0 or an empty string,
49	// so a module cannot mistake "not set" for a value.
50	export function workerParams(env, taskDir) {
51	  const text = (name) => (env[name] === undefined || env[name] === '' ? null : env[name]);
52	  const number = (name) => (text(name) === null ? null : Number(text(name)));
53	  const secrets = {};
54	  for (const name of declaredSecretNames(taskDir)) {
55	    if (env[name] !== undefined) secrets[name] = env[name];
56	  }
57	  return {
58	    root: text('CLAUDINITE_REPO_ROOT'),
59	    repo: text('CLAUDINITE_REPO'),
60	    defaultBranch: text('CLAUDINITE_DEFAULT_BRANCH'),
61	    pack: text('CLAUDINITE_PACK'),
62	    task: text('CLAUDINITE_TASK'),
63	    item: { number: number('CLAUDINITE_ITEM') },
64	    // One entry per Context bullet: the item's binding scope, and the channel an
65	    // operator's parameters ride.
66	    context: text('CLAUDINITE_CONTEXT') === null ? [] : text('CLAUDINITE_CONTEXT').split('\n'),
67	    target: {
