91	  const asked = [];
92	  // REPO SHAPE IS NOT A PRECONDITION (docs/PRINCIPLES.md). "This repo ships the store pipeline", "this repo is a canon
93	  // home with a fleet token" are facts adoption settled, not questions worth
94	  // re-asking every tick — so a repo that carries a pack but not one task's
95	  // subject names that task in `taskScheduler.disabledTasks` and it is never
96	  // asked. Read here rather than at pick, because the cheapest run is the one
97	  // that files no item at all.
98	  const disabled = new Set(schedule?.disabledTasks ?? []);
99	  const closedByThisRun = new Set();
100	
101	  // ---- the orphan reap ----------------------------------------------------
102	  // A blocked standing item whose `<pack>/<task>` is not declared at HEAD can
103	  // never execute — job 1 matches its family title-exact on the declared id, so a
104	  // legacy pack spelling is invisible to it, and job 2 would otherwise ready the
105	  // item at its Not-before and hand an executor a task path that is not on disk.
106	  // Guarded on a non-empty task list so an unreadable declaration reaps nothing,
107	  // and scoped to BLOCKED so nothing in flight is touched — a ready orphan is
108	  // picked within the tick and parks for a human, which is visible rather than
109	  // silent. Items waiting on a blocker are untouched: they are somebody's
110	  // dependency, not a schedule's.
111	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
112	  for (const item of items) {
113	    if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED) || !tasks.length) continue;
114	    const parsed = parseWorkItemTitle(item.title);
115	    if (!parsed || parsed.qualifier !== null) continue;
116	    const key = `${parsed.pack}/${parsed.task}`;
117	    if (parseWorkItemBody(item.body).blockedBy.length) continue;
118	    if (byId.has(key) && !disabled.has(key)) continue;
119	    closedByThisRun.add(item.number);
120	    ops.push({
121	      kind: 'retire-orphan', issue: item.number, pack: parsed.pack, task: parsed.task,
122	      reason: disabled.has(key)
123	        ? `Closing: \`${key}\` is named in this repository's \`taskScheduler.disabledTasks\`, so it is not `
124	          + 'asked here. Remove it from that list to bring the task back.'
125	        : `Closing: \`${key}\` is no longer declared on this repository, so this item names a task `

