// THE FAKE GITHUB ACTIONS — workflow runs as first-class events, and the runner
// environment the scheduler and the executor read themselves out of.
//
// It stands in for `src/world/actions.mjs`: `port` carries exactly that module's
// names, and the scenario levers hang off the harness beside it.
//
// A RUN IS THE BILLED UNIT, which is why this module keeps a ledger rather than
// a counter. Actions bills each JOB's wall time rounded UP to the minute, so a
// run that does nothing but read the hold and exit still costs a minute — and a
// design question like "what does an hourly cron cost on a quiet repo" is
// answered by the ledger's rows, never by how much work got done.
//
// The two workflow file names and the hold variable's name are IMPORTED from the
// real ports rather than restated: they are our own names, not the platform's,
// and a fake that spelled its own copy would go on passing after a rename.

import { EXECUTOR_WORKFLOW_FILE, SCHEDULER_WORKFLOW_FILE } from '../../../src/world/actions.mjs';
import { SUSPEND_ALL_VAR } from '../../../src/world/hold.mjs';
import { HOUR, MINUTE } from './clock.mjs';

const at_ = (when) => (typeof when === 'number' ? when : Date.parse(when));

export function makeActions({
  clock,
  github,
  repo = 'o/r',
  defaultBranch = 'main',
  root = '/repo',
  // The UTC hours the cron fires on — `null` is the every-hour grid. A member's
  // real cron names its hours explicitly, and what that costs and delays is a
  // question only a modelled grid can answer.
  cronHours = null,
  cronMinute = 17,
  // How long after the fire the runner actually starts. Actions does not start a
  // scheduled run at its cron instant, and a latency of zero is the one value
  // that is certainly wrong.
  startLatencyMs = 2 * MINUTE,
  env = {},
} = {}) {
  if (cronHours !== null && (!Array.isArray(cronHours) || cronHours.length === 0)) {
    // An empty list is not "the default grid" — it is a cron that never fires,
    // and every latency assertion over such a world passes vacuously.
    throw new Error('cronHours must be a non-empty array of UTC hours, or null for the every-hour grid');
  }

  const bag = { GITHUB_REPOSITORY: repo, GITHUB_REF_NAME: defaultBranch, GITHUB_SERVER_URL: 'https://github.com', ...env };
  const runs = [];            // the ledger: one row per started run
  const dropped = [];         // [fromMs, toMs) windows where the cron fire never arrives
  let runSeq = 0;
  let current = null;         // the run whose job is executing right now
  const busy = new Map();     // concurrency group -> the run holding it
  const waiting = new Set();  // groups with a run already queued behind the holder

  const idOf = (run) => `actions-${run.id}`;

  const port = {
    SCHEDULER_WORKFLOW_FILE,
    EXECUTOR_WORKFLOW_FILE,
    actionsEnv: () => (current ? { ...bag, ...current.env } : bag),
    repoRoot: () => root,
    // The simulator runs no subprocess, so nothing here ever runs with a task
    // directory as its cwd; the name exists so the parity check can see it, and it
    // answers what the real port would outside one.
    taskDir: () => root,
    actionRepoContext: (e = port.actionsEnv()) => ({
      repo: e.GITHUB_REPOSITORY || null,
      defaultBranch: e.GITHUB_REF_NAME || 'main',
    }),
    runUrl: (e = port.actionsEnv()) => (current ? `${e.GITHUB_SERVER_URL}/${e.GITHUB_REPOSITORY}/actions/runs/${current.id}` : null),
    runUrlFor: (slug, e = port.actionsEnv()) => (current ? `${e.GITHUB_SERVER_URL}/${slug}/actions/runs/${current.id}` : null),
    executorId: (e = port.actionsEnv()) => e.CLAUDINITE_EXECUTOR_ID || (current ? idOf(current) : 'actions-local'),
    // No output file outside a run, exactly as outside Actions — and the value
    // lands on the run's own row, which is where the next step reads it.
    setStepOutput: (name, value) => {
      if (!current) return false;
      current.outputs[name] = String(value);
      return true;
    },
  };

  // Start a run NOW. `body` may be async and takes as long as it takes — a job is
  // the unit the platform bills, so a run that does real work has to be able to
  // occupy real virtual time. `run.done` settles when the body does, and every
  // caller here awaits it: a run left floating would let the clock advance through
  // the middle of a job.
  //
  // `durationMs` is the declared length of a body that does nothing in particular;
  // `measure: true` says the body's own span is the length, which is what a run
  // driving the engine wants. `timeoutMs` is the ceiling the runner kills the job
  // at, and a killed job's body is simply ABANDONED — its promise is never awaited
  // again, exactly as a runner's process is not.
  function startRun({
    workflow, trigger, body = () => {}, durationMs = MINUTE, timeoutMs = null,
    concurrency = null, env: runEnv = {}, measure = false,
  }) {
    // THE CONCURRENCY GROUP, as `cancel-in-progress: false` actually behaves: one
    // run in progress and at most ONE pending behind it. A second run of the group
    // WAITS and then runs — which is what makes the scheduler run serialized rather
    // than skipped, and the whole reason its duplicate-standing-item self-heal can
    // never race itself. A third, arriving while one already waits, is the one the
    // platform supersedes.
    const held = concurrency && busy.get(concurrency);
    if (held) {
      if (waiting.has(concurrency)) {
        runs.push({
          id: (runSeq += 1), workflow, trigger, startedAt: clock.ms(), endedAt: clock.ms(),
          conclusion: 'superseded', outputs: {}, env: runEnv, done: Promise.resolve(), ended: Promise.resolve(),
        });
        return runs.at(-1);
      }
      waiting.add(concurrency);
      const queued = { done: null };
      // It waits for the holder to END — not for its body to settle. A run whose
      // length is declared rather than measured finishes its body at once and holds
      // the group until its declared end, and a waiter keyed on the body would
      // re-queue itself in a tight loop against a group still busy.
      queued.done = clock.park(held.ended).then(() => {
        waiting.delete(concurrency);
        const run = startRun({ workflow, trigger, body, durationMs, timeoutMs, concurrency, env: runEnv, measure });
        Object.assign(queued, run);
        return run.done;
      });
      return queued;
    }
    const run = {
      id: (runSeq += 1), workflow, trigger, startedAt: clock.ms(), endedAt: null,
      conclusion: null, outputs: {}, env: runEnv,
    };
    // When this run RELEASES its group, which is not when its body settles.
    let markEnded;
    run.ended = new Promise((r) => { markEnded = r; });
    runs.push(run);
    if (concurrency) busy.set(concurrency, run);

    const killAt = timeoutMs === null ? null : run.startedAt + timeoutMs;
    const finish = (conclusion) => {
      if (run.endedAt !== null) return;
      run.endedAt = clock.ms();
      run.conclusion = conclusion;
      if (concurrency && busy.get(concurrency) === run) busy.delete(concurrency);
      markEnded();
    };

    const previous = current;
    current = run;
    let outcome;
    try { outcome = body({ run, id: idOf(run) }); } finally { current = previous; }

    if (measure) {
      // The body IS the job: it ends when the body does, and the ledger bills what
      // it actually took. A body that throws is a job that failed — which is what
      // the continuation job downstream exists for.
      run.done = Promise.resolve(outcome).then(
        () => finish('success'),
        (e) => { finish('failure'); run.error = e; },
      );
      if (killAt !== null) clock.at(killAt, () => finish('cancelled'));
      return run;
    }

    const endAt = killAt === null ? run.startedAt + durationMs : Math.min(run.startedAt + durationMs, killAt);
    run.done = Promise.resolve(outcome).then(() => {}, (e) => { run.error = e; });
    clock.at(endAt, () => {
      if (run.endedAt !== null) return;
      run.endedAt = endAt;
      run.conclusion = killAt !== null && endAt === killAt && durationMs > timeoutMs ? 'cancelled' : 'success';
      if (concurrency && busy.get(concurrency) === run) busy.delete(concurrency);
      markEnded();
    });
    return run;
  }

  const harness = {
    port,
    runs: () => runs,
    startRun,
    // The env bag a scenario seeds a secret or an executor id into.
    env: bag,
    setEnv: (name, value) => { bag[name] = value; return harness; },

    // Book the cron grid across a window: one fire per hour on the grid, at
    // `cronMinute`, each starting `startLatencyMs` later — the run's START is
    // what the ledger records, because that is when the platform begins billing.
    cron: (fromIso, toIso, body, { concurrency = 'claudinite-scheduler', durationMs = MINUTE, measure = false } = {}) => {
      const from = at_(fromIso); const to = at_(toIso);
      for (let t = Math.ceil(from / HOUR) * HOUR + cronMinute * MINUTE; t < to; t += HOUR) {
        if (t < from) continue;
        if (cronHours && !cronHours.includes(new Date(t).getUTCHours())) continue;
        if (dropped.some(([a, b]) => t >= a && t < b)) continue;
        clock.at(t + startLatencyMs, () => startRun({
          workflow: SCHEDULER_WORKFLOW_FILE, trigger: 'schedule', body, durationMs, concurrency, measure,
        }).done);
      }
      return harness;
    },
    // GitHub drops scheduled fires under load: in [from, to) the run simply
    // never happens, which is a fact about the platform and not about us.
    dropFires: (fromIso, toIso) => { dropped.push([at_(fromIso), at_(toIso)]); return harness; },

    // Turn every `workflow_dispatch` the GitHub fake accepts into a run. The
    // ledger then counts the engine's REAL dispatch calls rather than a model's
    // idea of when a chain fires.
    runDispatches: (body, { durationMs = MINUTE, timeoutMs = null, measure = false } = {}) => {
      // A dispatch is a REQUEST for a run, and the platform starts it a moment
      // later on its own runner — never inside the call that asked for it. Booked
      // on the clock for that reason: a run that began inside the dispatching run's
      // own step would be draining the queue while the run that dispatched it was
      // still writing to it.
      github.onDispatch((fired) => clock.at(clock.ms() + startLatencyMs, () => startRun({
        workflow: fired.workflow, trigger: 'workflow_dispatch', body: (ctx) => body({ ...ctx, fired }),
        durationMs, timeoutMs, measure, env: fired.inputs ?? {},
      }).done));
      return harness;
    },

    // What the platform billed: each run's job rounded UP to the minute, which
    // is why a run that exited immediately still costs one.
    billedMinutes: () => runs
      .filter((r) => r.endedAt !== null)
      .reduce((sum, r) => sum + Math.max(1, Math.ceil((r.endedAt - r.startedAt) / MINUTE)), 0),
    runsOf: (workflow) => runs.filter((r) => r.workflow === workflow),

    // THE OPERATOR HOLD, set in the env bag a run starts with — the one place the
    // engine reads it (hold.mjs). A run already past its first act does not see it.
    suspendAll: () => { bag[SUSPEND_ALL_VAR] = 'true'; return harness; },
    resumeAll: () => { delete bag[SUSPEND_ALL_VAR]; return harness; },
  };
  return harness;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, readFileSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { removeTree } from '../../../../engine/remove-tree.mjs';
import { workerParams, emitVerdict, runWorkerModule } from '../../src/execute/worker-entry.mjs';
import { readTriageMarker, readRequeueMarker, readAgentRequest, agentRequested } from '../../src/execute/code-work.mjs';

// A task directory holding a declaration and a worker module, the shape the runner
// spawns the entry point in. The module name is unique per case: an ES module import
// is cached per URL, so two cases sharing a name would run the first one's code twice.
let seq = 0;
function taskDir({ decl = {}, worker = 'export const worker = () => {};\n' } = {}) {
  const dir = mkdtempSync(join(tmpdir(), 'claudinite-worker-entry-'));
  writeFileSync(join(dir, 'task.json'), JSON.stringify(decl));
  const file = `worker-${seq += 1}.mjs`;
  writeFileSync(join(dir, file), worker);
  return { dir, file };
}

const ENV = {
  CLAUDINITE_REPO_ROOT: '/checkout',
  CLAUDINITE_REPO: 'owner/name',
  CLAUDINITE_DEFAULT_BRANCH: 'main',
  CLAUDINITE_PACK: 'p',
  CLAUDINITE_TASK: 't',
  CLAUDINITE_ITEM: '42',
  CLAUDINITE_CONTEXT: 'first line\nsecond line',
  CLAUDINITE_TARGET_MODE: 'fresh',
  CLAUDINITE_TARGET_BRANCH: 'p/t-2026-09-22',
  CLAUDINITE_TARGET_PR: '77',
};

// The bag is the environment's parsed form: what every raw worker used to read for
// itself, read once here and handed over as data.
test('workerParams turns the code-work environment into the bag', () => {
  const { dir } = taskDir();
  try {
    const p = workerParams(ENV, dir);
    assert.equal(p.root, '/checkout');
    assert.equal(p.repo, 'owner/name');
    assert.equal(p.defaultBranch, 'main');
    assert.equal(p.pack, 'p');
    assert.equal(p.task, 't');
    assert.deepEqual(p.item, { number: 42 });
    assert.deepEqual(p.context, ['first line', 'second line']);
    assert.deepEqual(p.target, { mode: 'fresh', branch: 'p/t-2026-09-22', pr: 77 });
    assert.equal(workerParams({ ...ENV, GITHUB_TOKEN: 'ght' }, dir).token, 'ght');
    assert.equal(p.token, null, 'a run outside Actions carries none, and says so');
  } finally { removeTree(dir); }
});

// Unknown is a state of its own: a run with no pull request to amend must not read as
// PR 0, and a task with no Context as one empty bullet.
test('workerParams keeps an unset value null, and an unset Context empty', () => {
  const { dir } = taskDir();
  try {
    const p = workerParams({ ...ENV, CLAUDINITE_TARGET_PR: '', CLAUDINITE_CONTEXT: '' }, dir);
    assert.equal(p.target.pr, null);
    assert.deepEqual(p.context, []);
    const bare = workerParams({}, dir);
    assert.equal(bare.item.number, null);
    assert.equal(bare.repo, null);
    assert.deepEqual(bare.target, { mode: null, branch: null, pr: null });
  } finally { removeTree(dir); }
});

// Only the secrets the task DECLARED, read off the declaration beside the module
// rather than through a channel of its own - and a declared one the repo has not
// configured is absent from the bag, never an empty string.
test('workerParams bags the declared secrets only', () => {
  const { dir } = taskDir({ decl: { code_work_required_secrets: ['WANTED', 'UNSET'] } });
  try {
    const p = workerParams({ ...ENV, WANTED: 'v', OTHER: 'no' }, dir);
    assert.deepEqual(p.secrets, { WANTED: 'v' });
  } finally { removeTree(dir); }
});

test('workerParams reads the retired required_secrets spelling too', () => {
  const { dir } = taskDir({ decl: { required_secrets: ['WANTED'] } });
  try {
    assert.deepEqual(workerParams({ WANTED: 'v' }, dir).secrets, { WANTED: 'v' });
  } finally { removeTree(dir); }
});

// --- the verdict, rendered into the protocol the executor reads -------------------

test('emitVerdict prints the triage and requeue markers the executor parses', () => {
  const out = [];
  emitVerdict({ triage: { kind: 'action', detail: 'TOKEN lacks Actions: write' } }, { log: (l) => out.push(l) });
  emitVerdict({ requeue: { until: '2026-09-01T12:00:00Z', reason: 'not yet live' } }, { log: (l) => out.push(l) });
  assert.deepEqual(out, [
    'claudinite-needs-human: action - TOKEN lacks Actions: write',
    'claudinite-requeue: 2026-09-01T12:00:00Z - not yet live',
  ]);
});

// One wire format with an emitter here and a parser in code-work.mjs: the executor
// reads these lines out of the run's output, so a separator or a prefix the emitter
// changes on its own would be read as part of the detail, or not read at all.
test('what emitVerdict prints is what the executor parses back', () => {
  const out = [];
  emitVerdict({
    triage: { kind: 'action', detail: 'TOKEN lacks Actions: write' },
    requeue: { until: '2026-09-01T12:00:00Z', reason: 'not yet live' },
  }, { log: (l) => out.push(l) });
  const text = out.join('\n');
  assert.deepEqual(readTriageMarker(text), { kind: 'action', detail: 'TOKEN lacks Actions: write' });
  assert.deepEqual(readRequeueMarker(text), { until: '2026-09-01T12:00:00.000Z', reason: 'not yet live' });
  // A verdict with no detail parses as one, rather than as a detail of punctuation.
  const bare = [];
  emitVerdict({ triage: { kind: 'decision' }, requeue: { until: '2026-09-01T12:00:00Z' } }, { log: (l) => bare.push(l) });
  assert.deepEqual(readTriageMarker(bare.join('\n')), { kind: 'decision', detail: null });
  assert.deepEqual(readRequeueMarker(bare.join('\n')), { until: '2026-09-01T12:00:00.000Z', reason: null });
});

test('emitVerdict writes the agent request, carrying delivered and reason', () => {
  const dir = mkdtempSync(join(tmpdir(), 'claudinite-worker-entry-'));
  const requestPath = join(dir, 'request');
  try {
    emitVerdict({ requestAgent: { delivered: { pr: 5, branch: 'b' }, reason: { code: 'diff', detail: '3 files' } } },
      { requestPath, log: () => {} });
    // Read back through the executor's own reader, which is what the hand-off uses.
    assert.equal(agentRequested(requestPath), true);
    assert.deepEqual(readAgentRequest(requestPath), {
      delivered: { pr: 5, branch: 'b' },
      reason: { code: 'diff', detail: '3 files' },
    });
  } finally { removeTree(dir); }
});

// The file's EXISTENCE is the control signal, so a bare request is a legal one.
test('emitVerdict writes a bare request for requestAgent: true', () => {
  const dir = mkdtempSync(join(tmpdir(), 'claudinite-worker-entry-'));
  const requestPath = join(dir, 'request');
  try {
    emitVerdict({ requestAgent: true }, { requestPath, log: () => {} });
    assert.deepEqual(JSON.parse(readFileSync(requestPath, 'utf8')), {});
  } finally { removeTree(dir); }
});

test('emitVerdict writes nothing for a worker that returned nothing', () => {
  const dir = mkdtempSync(join(tmpdir(), 'claudinite-worker-entry-'));
  const requestPath = join(dir, 'request');
  const out = [];
  try {
    emitVerdict(undefined, { requestPath, log: (l) => out.push(l) });
    assert.deepEqual(out, []);
    assert.equal(existsSync(requestPath), false);
  } finally { removeTree(dir); }
});

// --- the whole wrapping ----------------------------------------------------------

const capture = () => {
  const log = []; const err = [];
  return { log, err, io: { log: (l) => log.push(l), err: (l) => err.push(l) } };
};

test('runWorkerModule calls the worker with the bag and reports the time it took', async () => {
  const { dir, file } = taskDir({
    worker: 'export const worker = (params) => { globalThis.__seen = params; };\n',
  });
  const { log, err, io } = capture();
  let clock = 1000;
  try {
    const r = await runWorkerModule(file, { env: ENV, taskDir: dir, ...io, now: () => (clock += 2500) });
    assert.equal(r.ok, true);
    assert.equal(globalThis.__seen.repo, 'owner/name');
    assert.deepEqual(globalThis.__seen.item, { number: 42 });
    assert.deepEqual(err, []);
    assert.match(log.at(-1), /^p\/t: worker done in 2\.5s$/);
  } finally { delete globalThis.__seen; removeTree(dir); }
});

// The failure line the executor's park comment is built from, and the exit the
// caller sets from it - a throw is the worker's only failure channel.
test('runWorkerModule turns a throw into the failure line, the stack, and not-ok', async () => {
  const { dir, file } = taskDir({ worker: 'export const worker = () => { throw new Error("upstream 500"); };\n' });
  const { log, err, io } = capture();
  try {
    const r = await runWorkerModule(file, { env: ENV, taskDir: dir, ...io, now: () => 0 });
    assert.equal(r.ok, false);
    assert.match(err[0], /^p\/t failed after 0\.0s: upstream 500$/);
    assert.match(err[1], /Error: upstream 500/, 'the stack follows the line');
    assert.equal(log.length, 0, 'no completion line for a run that failed');
  } finally { removeTree(dir); }
});

// The worker is the only thing that can tell a missing scope from a bug in its own
// code, so an error carrying that diagnosis routes the park.
test('runWorkerModule prints the triage marker of an error that carries one', async () => {
  const { dir, file } = taskDir({
    worker: 'export const worker = () => { const e = new Error("TOKEN lacks Actions: write"); e.triage = "action"; throw e; };\n',
  });
  const { err, io } = capture();
  try {
    const r = await runWorkerModule(file, { env: ENV, taskDir: dir, ...io, now: () => 0 });
    assert.equal(r.ok, false);
    assert.equal(err[0], 'claudinite-needs-human: action - TOKEN lacks Actions: write');
  } finally { removeTree(dir); }
});

// A module that does not hold up its half of the contract fails as a failed run,
// naming what it is missing: the runner calls exactly one export.
test('runWorkerModule fails a module that exports no worker', async () => {
  const { dir, file } = taskDir({ worker: 'export const main = () => {};\n' });
  const { err, io } = capture();
  try {
    const r = await runWorkerModule(file, { env: ENV, taskDir: dir, ...io, now: () => 0 });
    assert.equal(r.ok, false);
    assert.match(err[0], /exports no `worker` function/);
  } finally { removeTree(dir); }
});

test('runWorkerModule fails a module that is not there', async () => {
  const { dir } = taskDir();
  const { err, io } = capture();
  try {
    const r = await runWorkerModule('absent.mjs', { env: ENV, taskDir: dir, ...io, now: () => 0 });
    assert.equal(r.ok, false);
    assert.match(err[0], /^p\/t failed after/);
  } finally { removeTree(dir); }
});

// An async worker is awaited: a module returning a promise must not be reported done
// before its work settles, nor have a rejection escape as an unhandled one.
test('runWorkerModule awaits an async worker, verdict and rejection alike', async () => {
  const done = taskDir({
    worker: 'export const worker = async () => { await new Promise((r) => setTimeout(r, 5)); return { triage: { kind: "decision" } }; };\n',
  });
  const failed = taskDir({ worker: 'export const worker = async () => { throw new Error("late"); };\n' });
  const a = capture();
  const b = capture();
  try {
    assert.equal((await runWorkerModule(done.file, { env: ENV, taskDir: done.dir, ...a.io, now: () => 0 })).ok, true);
    assert.equal(a.log[0], 'claudinite-needs-human: decision');
    assert.equal((await runWorkerModule(failed.file, { env: ENV, taskDir: failed.dir, ...b.io, now: () => 0 })).ok, false);
    assert.match(b.err[0], /late/);
  } finally { removeTree(done.dir); removeTree(failed.dir); }
});

// What code-work hands the agentic phase, on the queue's dispatch path — the twin of
// dispatch.mjs's `deliveredLines` for the slot path. The two render the same payload
// into different carriers (a work item's section vs a dispatch issue's body), so a key
// added to one and not the other is dropped silently on half the fleet.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
