1	// THE RUNNER'S OWN ENTRY POINT for a task declaring `code_worker_mjs` (owner,
2	// 2026-09-22). The runner already owns the subprocess - it builds the command, sets
3	// the environment, bounds the run and echoes the output - so it owns the entry point
4	// too, and a worker module holds the work and nothing else.
5	//
6	// What every raw `code_work` worker re-implemented, and what lives here once:
7	//
8	//   - THE PARAMETERS BAG. The CLAUDINITE_* environment is read here and handed over
9	//     as data, so a module never touches `process.env` and can be called directly
10	//     from a test with a bag it built itself. The environment stays the wire -
11	//     nothing new crosses the process boundary - and `params` is its parsed form.
12	//   - THE EXIT. `process.exitCode`, never `process.exit()`: a worker's output is the
13	//     run's only trace, and a hard exit discards whatever the pipe has not drained.
14	//   - THE FAILURE LINE. A throw becomes the `<pack>/<task> failed: ...` line plus the
15	//     stack, and an error carrying `.triage` also prints the marker that routes the
16	//     park - the diagnosis a worker is the only thing able to make.
17	//   - THE TIMING. How long the work took, on the run's own log, where a code-work
18	//     creeping towards its `code_work_timeout` is visible before it is killed.
19	//   - THE QUEUE'S MARKERS. A returned `triage` or `requeue` becomes the marker the
20	//     executor reads, and a returned `requestAgent` becomes the request file. A
21	//     module states its verdict as a value; the protocol is written here.
22	//
23	// The module is imported rather than spawned, so it runs in this process with the
24	// task directory as cwd - the same containment `code_work` has.
25	
26	import { readFileSync, writeFileSync } from 'node:fs';
27	import { pathToFileURL } from 'node:url';
28	import { resolve } from 'node:path';
29	import { actionsEnv, taskDir as cwdTaskDir } from '../world/actions.mjs';
30	import { nowMs } from '../world/clock.mjs';
31	
32	// The declaration beside the module. Read for the one thing the environment does not
33	// carry - which secrets this task asked for - rather than passed in a channel of its
34	// own: the module sits in its task directory, so the declaration is already here.
35	function declaredSecretNames(taskDir) {
36	  try {
37	    const decl = JSON.parse(readFileSync(resolve(taskDir, 'task.json'), 'utf8'));
38	    const names = decl.code_work_required_secrets ?? decl.required_secrets;
39	    return Array.isArray(names) ? names.filter((n) => typeof n === 'string') : [];
40	  } catch {
41	    // A task whose declaration cannot be read here is one the executor validated
42	    // before spawning this process, so the file is present and parseable in every
43	    // real run; an empty bag is the honest answer for the cases that are not.
44	    return [];
45	  }
46	}
47	
48	// The bag a worker is called with. Absence is preserved rather than defaulted: a
49	// target this run has no pull request for reads `null`, never 0 or an empty string,
50	// so a module cannot mistake "not set" for a value.
51	export function workerParams(env, taskDir) {
52	  const text = (name) => (env[name] === undefined || env[name] === '' ? null : env[name]);
53	  const number = (name) => (text(name) === null ? null : Number(text(name)));
54	  const secrets = {};
55	  for (const name of declaredSecretNames(taskDir)) {
56	    if (env[name] !== undefined) secrets[name] = env[name];
57	  }
58	  return {
59	    root: text('CLAUDINITE_REPO_ROOT'),
60	    // The executor always sets `CLAUDINITE_REPO`; the runner's own variable is the
61	    // fallback every raw worker wrote for itself, kept so the bag answers the same
62	    // question outside a code-work run as inside one.
63	    repo: text('CLAUDINITE_REPO') ?? text('GITHUB_REPOSITORY'),
64	    defaultBranch: text('CLAUDINITE_DEFAULT_BRANCH'),
65	    pack: text('CLAUDINITE_PACK'),
66	    task: text('CLAUDINITE_TASK'),
67	    item: { number: number('CLAUDINITE_ITEM') },
68	    // One entry per Context bullet: the item's binding scope, and the channel an
69	    // operator's parameters ride.
70	    context: text('CLAUDINITE_CONTEXT') === null ? [] : text('CLAUDINITE_CONTEXT').split('\n'),
71	    target: {
72	      mode: text('CLAUDINITE_TARGET_MODE'),
73	      branch: text('CLAUDINITE_TARGET_BRANCH'),
74	      pr: number('CLAUDINITE_TARGET_PR'),
75	    },
76	    // The Action's own token, which every worker that talks to GitHub needs and each
77	    // one used to reach into the environment for: handed over so `makeGh({ token })`
78	    // is written rather than implied. A run outside Actions has none, and `null` says
79	    // so where a worker can report it.
80	    token: text('GITHUB_TOKEN'),
81	    // Where the runner collects the job summary a person reads on the run's page.
82	    // Absent outside Actions, which is a worker's cue to print instead of append.
83	    stepSummary: text('GITHUB_STEP_SUMMARY'),
84	    secrets,
85	  };
86	}
87	
88	// A worker's returned verdict, rendered into the protocol the executor reads. Every
89	// key is optional, and a worker that returns nothing at all has simply done its work.
90	export function emitVerdict(verdict, { env = actionsEnv(), log = console.log, requestPath = null } = {}) {
91	  const out = verdict ?? {};
92	  if (out.triage) {
93	    const detail = out.triage.detail ? ` - ${out.triage.detail}` : '';
94	    log(`claudinite-needs-human: ${out.triage.kind}${detail}`);
95	  }
96	  if (out.requeue) {
97	    const reason = out.requeue.reason ? ` - ${out.requeue.reason}` : '';
98	    log(`claudinite-requeue: ${out.requeue.until}${reason}`);
99	  }
100	  if (out.requestAgent) {
101	    // The control signal is the file's EXISTENCE; its body carries only what the
102	    // named exception lets cross to the agent - what this run created, and the name
103	    // of the condition that woke it.
104	    const path = requestPath ?? env.CLAUDINITE_REQUEST_AGENT;
105	    if (!path) throw new Error('the worker requested the agent, but no CLAUDINITE_REQUEST_AGENT path was handed in');
106	    const { delivered = undefined, reason = undefined } = out.requestAgent === true ? {} : out.requestAgent;
107	    writeFileSync(path, JSON.stringify({ ...(delivered ? { delivered } : {}), ...(reason ? { reason } : {}) }));
108	  }
109	}
