119	    const mod = await import(pathToFileURL(resolve(taskDir, file)).href);
120	    if (typeof mod.worker !== 'function') {
121	      throw new Error(`${file} exports no \`worker\` function - the runner calls that export with the parameters bag`);
122	    }
123	    const verdict = await mod.worker(workerParams(env, taskDir));
124	    emitVerdict(verdict, { env, log });
125	    log(`${id}: worker done in ${((now() - started) / 1000).toFixed(1)}s`);
126	    return { ok: true };
