import re, sys

START = re.compile(r"^(if \(process\.argv\[1\]|const isMain = process\.argv\[1\])")

def strip_guard(lines):
    for i, line in enumerate(lines):
        if START.match(line):
            start = i
            # the `const isMain = ...` form is a statement, and the `if (isMain) {` beneath it
            if line.startswith('const isMain'):
                end = i
                while not lines[end].startswith('if (isMain)'):
                    end += 1
                start_block = end
            else:
                start_block = i
            depth = 0
            j = start_block
            while True:
                depth += lines[j].count('{') - lines[j].count('}')
                if depth <= 0 and '{' in ''.join(lines[start_block:j + 1]):
                    break
                j += 1
            while start > 0 and lines[start - 1].startswith('//'):
                start -= 1
            while start > 0 and lines[start - 1].strip() == '':
                start -= 1
            return lines[:start] + lines[j + 1:], True
    return lines, False

for path in sys.argv[1:]:
    lines = open(path).read().split('\n')
    lines, found = strip_guard(lines)
    assert found, path
    open(path, 'w').write('\n'.join(lines).rstrip('\n') + '\n')
    print('guard stripped', path)
